#[doc = r" Look up a vanilla datapack resource by namespace and path."]
#[must_use]
pub fn get_vanilla_resource(namespace: &str, path: &str) -> Option<&'static [u8]> {
    let idx = INDEX
        .binary_search_by(|entry| match entry.ns.cmp(namespace) {
            std::cmp::Ordering::Equal => entry.path.cmp(path),
            other => other,
        })
        .ok()?;
    let e = &INDEX[idx];
    Some(&DATA[e.offset..e.offset + e.len])
}
#[doc = r" Returns all namespaces with embedded vanilla data."]
#[must_use]
pub fn get_vanilla_namespaces() -> &'static [&'static str] {
    &["minecraft"]
}
